package com.example.agendapersonal;
import android.content.ContentValues;import android.database.Cursor;
import com.example.agendapersonal.data.DatabaseHelper;import com.example.agendapersonal.sync.*;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;

/** Hereda las ocho pruebas anteriores. Todas usan una base UUID aislada, sin red ni cuenta real. */
public class PersistenciaSyncInstrumentedTest extends AlmacenSyncInstrumentedTest {
 CambioSync snapshot(JSONObject p)throws Exception{CambioSync c=cambio("personas",p,p.getInt("revision")-1);JSONObject j=new JSONObject(c.documento).put("_snapshot",true);return new CambioSync(c.id,c.fecha,j.toString());}
 void recibir(CambioSync c)throws Exception{store.preparar(c,OWNER,DEVICE);assertTrue(store.aplicar(c,OWNER,DEVICE));}
 void sql(String s){try(DatabaseHelper h=new DatabaseHelper(context)){h.getWritableDatabase().execSQL(s);}}
 void log(CambioSync c)throws Exception{JSONObject j=new JSONObject(c.documento);ContentValues v=new ContentValues();for(String k:new String[]{"change_id","owner_id","device_id","entity_type","entity_id","operation","created_at"})v.put(k,j.getString(k));v.put("base_revision",j.getInt("base_revision"));v.put("entity_revision",j.getInt("entity_revision"));v.put("payload",j.getJSONObject("payload").toString());try(DatabaseHelper h=new DatabaseHelper(context)){h.getWritableDatabase().insertOrThrow("sync_changes",null,v);}}
 @Test public void dispositivoNuevoRecibeRevisionAltaSinHistorialAnterior()throws Exception{recibir(snapshot(persona("Estado permanente",15)));assertEquals("Estado permanente",nombre(context));assertEquals(1,cantidad("sync_changes"));assertEquals(0,store.cantidadPendientes(OWNER));}
 @Test public void dispositivoInactivoSaltaRevisionesPodadasConBaseLimpia()throws Exception{recibir(snapshot(persona("Antes",1)));recibir(snapshot(persona("Después de 90 días",12)));assertEquals("Después de 90 días",nombre(context));assertEquals(0,store.cantidadConflictos(OWNER));}
 @Test public void baseRemotaSobreviveReinicio()throws Exception{recibir(snapshot(persona("Antes",1)));store.close();store=new AlmacenSync(context);recibir(snapshot(persona("Nueva",9)));assertEquals("Nueva",nombre(context));}
 @Test public void snapshotNoPisaEdicionLocalSinEnviar()throws Exception{recibir(snapshot(persona("Base",1)));sql("UPDATE personas SET nombre='Local',revision=2");CambioSync local=cambio("personas",persona("Local",2),1);log(local);CambioSync remoto=snapshot(persona("Otra",7));store.preparar(remoto,OWNER,DEVICE);assertFalse(store.aplicar(remoto,OWNER,DEVICE));assertEquals("Local",nombre(context));assertEquals(1,store.cantidadConflictos(OWNER));assertEquals(1,store.salientes(OWNER,100).size());}
 @Test public void snapshotNoPisaEdicionEnviadaQueServidorConservoComoConflicto()throws Exception{recibir(snapshot(persona("Base",1)));sql("UPDATE personas SET nombre='Mi rama',revision=2");CambioSync local=cambio("personas",persona("Mi rama",2),1);log(local);store.confirmarEnviados(OWNER,Collections.singletonList(local));CambioSync remoto=snapshot(persona("Rama aceptada",2));store.preparar(remoto,OWNER,DEVICE);assertFalse(store.aplicar(remoto,OWNER,DEVICE));assertEquals("Mi rama",nombre(context));assertEquals(1,store.cantidadConflictos(OWNER));}
 @Test public void bajaPermaneceAunqueLlegueSnapshotViejo()throws Exception{recibir(snapshot(persona("Borrada",9).put("deleted_at","2026-11-05T12:00:00Z")));CambioSync vieja=snapshot(persona("Vieja",2));store.preparar(vieja,OWNER,DEVICE);assertFalse(store.aplicar(vieja,OWNER,DEVICE));try(DatabaseHelper h=new DatabaseHelper(context);Cursor c=h.getReadableDatabase().rawQuery("SELECT deleted_at FROM personas",null)){assertTrue(c.moveToFirst());assertFalse(c.isNull(0));}}
 @Test public void limpiezaLocalQuitaTransporteYConservaDatos()throws Exception{CambioSync c=snapshot(persona("Conservar",5));recibir(c);store.confirmarRecibos(OWNER,DEVICE,Collections.singletonList(c.id));sql("UPDATE sync_outbox_sent SET confirmed_at='2000-01-01T00:00:00Z'");sql("UPDATE sync_inbox_receipts SET applied_at='2000-01-01T00:00:00Z'");store.limpiarConfirmados(OWNER);assertEquals("Conservar",nombre(context));assertEquals(0,cantidad("sync_changes"));assertEquals(0,cantidad("sync_deferred"));assertEquals(0,cantidad("sync_inbox_receipts"));recibir(snapshot(persona("Recuperada sin cambios anteriores",11)));assertEquals("Recuperada sin cambios anteriores",nombre(context));}
 @Test public void limpiezaConservaSalidaNoConfirmada()throws Exception{insertar(context,persona("Sin enviar",1));CambioSync c=cambio("personas",persona("Sin enviar",1),0);log(c);sql("UPDATE sync_changes SET created_at='2000-01-01T00:00:00Z'");store.limpiarConfirmados(OWNER);assertEquals(1,cantidad("sync_changes"));assertEquals(1,store.salientes(OWNER,100).size());}
 @Test public void limpiezaConservaConflictoSinResolver()throws Exception{recibir(snapshot(persona("Base",1)));sql("UPDATE personas SET nombre='Local',revision=2");CambioSync remoto=snapshot(persona("Divergente",2));store.preparar(remoto,OWNER,DEVICE);assertFalse(store.aplicar(remoto,OWNER,DEVICE));sql("UPDATE sync_outbox_sent SET confirmed_at='2000-01-01T00:00:00Z'");store.limpiarConfirmados(OWNER);assertEquals(1,store.cantidadConflictos(OWNER));assertEquals(1,cantidad("sync_changes"));assertEquals("Local",nombre(context));}
}
